import random

class Solution:
    def kthLargestNumber(self, nums: List[str], k: int) -> str:
        def nth_element(nums, n, compare=lambda a, b: a < b):
            def tri_partition(nums, left, right, target, compare):
                mid = left
                while mid <= right:
                    if nums[mid] == target:
                        mid += 1
                    elif compare(nums[mid], target):
                        nums[left], nums[mid] = nums[mid], nums[left]
                        left += 1
                        mid += 1
                    else:
                        nums[mid], nums[right] = nums[right], nums[mid]
                        right -= 1
                return left, right

            left, right = 0, len(nums)-1
            while left <= right:
                pivot_idx = random.randint(left, right)
                pivot_left, pivot_right = tri_partition(nums, left, right, nums[pivot_idx], compare)
                if pivot_left <= n <= pivot_right:
                    return
                elif pivot_left > n:
                    right = pivot_left-1
                else:  # pivot_right < n.
                    left = pivot_right+1

        nth_element(nums, k-1, compare=lambda a, b: a > b if len(a) == len(b) else len(a) > len(b))
        return nums[k-1]

class Solution:
    def minSessions(self, tasks, T):
        n = len(tasks)

        @lru_cache(None)
        def dp(mask):
            if mask == 0: return (1, 0)
            ans = (float("inf"), float("inf"))
            for j in range(n):
                if mask & (1<<j):
                    pieces, last = dp(mask - (1 << j))
                    full = (last + tasks[j] > T)
                    ans = min(ans, (pieces + full, tasks[j] + (1-full)*last))  
            return ans

        return dp((1<<n) - 1)[0]

class Solution:
    def minSessions(self, tasks, sessionTime):
        # dp[mask][0]: min number of sessions by choosing tasks in mask bitset
        # dp[mask][1]: min used time of last session by choosing tasks in mask bitset
        dp = [[float("inf")]*2 for _ in range(1<<len(tasks))]
        dp[0] = [0, sessionTime]
        for mask in range(len(dp)-1):
            basis = 1
            for task in tasks:
                new_mask = mask|basis
                basis <<= 1
                if new_mask == mask:
                    continue
                if dp[mask][1]+task <= sessionTime:
                    dp[new_mask] = min(dp[new_mask], [dp[mask][0], dp[mask][1]+task])
                else:
                    dp[new_mask] = min(dp[new_mask], [dp[mask][0]+1, task])
        return dp[-1][0]

class Solution:
    def minSessions(self, tasks, sessionTime):
        # dp[mask]: min used time by choosing tasks in mask bitset
        dp = [float("inf") for _ in range(1<<len(tasks))]
        dp[0] = 0
        for mask in range(len(dp)-1):
            basis = 1
            for task in tasks:
                new_mask = mask|basis
                basis <<= 1
                if new_mask == mask:
                    continue
                if dp[mask]%sessionTime + task > sessionTime:
                    task += sessionTime-dp[mask]%sessionTime  # take a break
                dp[new_mask] = min(dp[new_mask], dp[mask]+task)
        return (dp[-1]+sessionTime-1)//sessionTime

class Solution:
    def numberOfUniqueGoodSubsequences(self, binary: str) -> int:


        # zero_as_last: the count of S0, good sequence ending in 0
        # one_as_last : the count of S1: good sequence ending in 1
        # zero_exist:   existence flag of 0 in given binary

        dp = {"zero_as_last": 0, "one_as_last": 0, "zero_exist": 0}

        for bit in map(int, binary):

            if bit:
                # current good = ( S0 concate with 1 ) + ( S1 concate with 1 ) + 1 alone
                # + "1" is allowed because leading 1 is valid by description
                dp["one_as_last"] = dp["zero_as_last"] + dp["one_as_last"] + 1

            else:
                # current good = ( S0 concate with 0 ) + ( S1 concate with 0 ) 
                # + "0" is NOT allowed because leading 0 is invalid by description
                dp["zero_as_last"] = dp["zero_as_last"] + dp["one_as_last"]

            # check the existence of 0
            dp["zero_exist"] |= (1-bit)


        return sum( dp.values() ) % ( 10**9 + 7 )

class Solution:
    def numberOfUniqueGoodSubsequences(self, binary: str) -> int:
        MOD = 10**9+7
        ends0, ends1 = 0, 0
        has_zero = False
        for b in binary:
            if b == '1':
                ends1 = (ends0+ends1+1)%MOD  # curr subsequences end with 1 is all prev distinct subsequences appended by 1 and plus "1"
            else:
                ends0 = (ends0+ends1)%MOD  # curr subsequences end with 0 is all prev distinct subsequences appended by 0 and don't plus "0"
                has_zero = True
        return (ends0+ends1+int(has_zero))%MOD  # add "0" if has_zero

